70: function Get-McpBackgroundScopeKey {
71:     <#
72:     .SYNOPSIS
73:         TR-MCP-PLUGIN-013 AC-005 (PLAN-SESSIONTRIAGEFIX-001 D3): the identity of a background host: MCP_SUBAGENT_ID, else GROK_SUBAGENT_ID,
74:         else the hook payload's session_id. None when there is none or when it equals the agentSessionId recorded for the root, because
75:         then the prompt is the root host's own.
76:     #>
77:     [CmdletBinding()]
78:     param(
79:         [string]$PayloadSessionId,
80:         [string]$RootAgentSessionId
81:     )
82: 
83:     $key = @($env:MCP_SUBAGENT_ID, $env:GROK_SUBAGENT_ID, $PayloadSessionId) |
84:         Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -First 1
85:     if ([string]::IsNullOrWhiteSpace($key)) { return $null }
86:     $key = $key.Trim()
87:     if (-not [string]::IsNullOrWhiteSpace($RootAgentSessionId) -and
88:         [string]::Equals($key, $RootAgentSessionId.Trim(), [System.StringComparison]::Ordinal)) {
89:         return $null
90:     }
91:     return $key
92: }
