153: function Resolve-McpCacheDir {
154:     [CmdletBinding()]
155:     param([string]$StartPath)
156: 
157:     if ($env:MCP_CACHE_DIR_OVERRIDE) {
158:         return $env:MCP_CACHE_DIR_OVERRIDE
159:     }
160: 
161:     if (-not (Get-Command Find-MarkerFile -ErrorAction SilentlyContinue)) {
162:         $resolver = Join-Path $script:ResolveCacheDirScriptDir 'marker-resolver.ps1'
163:         if (Test-Path -LiteralPath $resolver) {
164:             . $resolver
165:         }
166:     }
167: 
168:     $explicitWorkspace = @(
169:         $env:MCP_WORKSPACE_PATH,
170:         $env:MCPSERVER_WORKSPACE_PATH,
171:         $env:CLAUDE_PROJECT_DIR
172:     ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) -and (Test-Path -LiteralPath $_ -PathType Container) } | Select-Object -First 1
173: 
174:     if ([string]::IsNullOrWhiteSpace($StartPath) -and $explicitWorkspace) {
175:         return (Join-McpWorkspaceCachePath -WorkspacePath ((Resolve-Path -LiteralPath $explicitWorkspace).ProviderPath))
176:     }
177: 
178:     $startCandidates = if (-not [string]::IsNullOrWhiteSpace($StartPath)) {
179:         @($StartPath)
180:     } else {
181:         @(
182:             $env:CODEX_CWD,
183:             (Get-Location).Path
184:         ) | Where-Object { -not [string]::IsNullOrWhiteSpace($_) } | Select-Object -Unique
185:     }
186: 
187:     if (Get-Command Find-MarkerFile -ErrorAction SilentlyContinue) {
188:         foreach ($startDir in $startCandidates) {
189:             try {
190:                 $markerFile = Find-MarkerFile -StartDir $startDir
191:                 if ($markerFile) {
192:                     return (Join-McpWorkspaceCachePath -WorkspacePath (Split-Path -Parent $markerFile))
193:                 }
194:             } catch {
195:                 # Try the next active start candidate, then configured env.
196:             }
197:         }
198:     }
199: 
200:     $configuredWorkspace = Get-McpWorkspaceFromEnvironment
201:     if ($configuredWorkspace) {
202:         return (Join-McpWorkspaceCachePath -WorkspacePath $configuredWorkspace)
203:     }
204: 
205:     throw "Unable to resolve the active workspace cache. Set MCP_WORKSPACE_PATH or MCP_CACHE_DIR_OVERRIDE; plugin install paths are not workspace caches."
206: }
