6: /// <summary>
7: /// TR-MCP-USECASE-018 (AC-006), TR-MCP-USECASE-019 (AC-008): finds platform dependence in unit test classes.
8: /// A test that depends on the platform is an integration test (operator 2026-10-19: "If it depends on the
9: /// environment, it's an integration test."), so an operating-system check, an OS-platform attribute, an
10: /// xUnit skip, or a binding to the real process host is a finding unless its test class (or an enclosing
11: /// class) carries <c>[Trait("Category", "Integration")]</c>. Strings and comments are ignored. Test classes
12: /// are types whose name ends in <c>Tests</c> or that declare <c>[Fact]</c> or <c>[Theory]</c> methods; other
13: /// helper types (for example the host-neutral <c>UnitTestPaths</c> fixture) are not test classes.
14: /// </summary>
15: internal static class UnitSuitePlatformScanner
16: {
17:     private static readonly (string Kind, Regex Pattern)[] Rules =
18:     [
19:         ("os-check", new Regex(@"\bOperatingSystem\s*\.\s*Is[A-Z]\w*\s*\(", RegexOptions.CultureInvariant)),
20:         ("os-check", new Regex(@"\bRuntimeInformation\s*\.\s*IsOSPlatform\s*\(", RegexOptions.CultureInvariant)),
21:         ("os-attribute", new Regex(@"\[\s*(?:[\w.]+\.)?(?:Supported|Unsupported)OSPlatform(?:Attribute)?\s*\(", RegexOptions.CultureInvariant)),
22:         ("skip", new Regex(@"\bAssert\s*\.\s*Skip(?:When|Unless)?\s*\(|\bSkipException\b|\bSkippable(?:Fact|Theory)\b|\[\s*(?:Fact|Theory)\s*\([^\]]*\bSkip\s*=", RegexOptions.CultureInvariant)),
23:         ("process-host", new Regex(@"\bSystemWorkspaceHostEnvironment\s*\.\s*Instance\b|\bWorkspacePathNormalizer\s*\.\s*Process\b", RegexOptions.CultureInvariant)),
24:     ];
25: 
26:     private static readonly Regex TypeDeclaration = new(
27:         @"\b(?:class|record|struct|interface)\s+([A-Za-z_]\w*)",
28:         RegexOptions.CultureInvariant);
29: 
30:     private static readonly Regex IntegrationTrait = new(
31:         @"\[\s*(?:Xunit\.)?Trait(?:Attribute)?\s*\(\s*""Category""\s*,\s*""Integration""\s*\)",
32:         RegexOptions.CultureInvariant);
33: 
34:     private static readonly Regex TestAttribute = new(@"\[\s*(?:Xunit\.)?(?:Fact|Theory)\b", RegexOptions.CultureInvariant);
35: 
36:     /// <summary>Scans one C# source file and returns its findings in line order.</summary>
37:     /// <param name="relativePath">Path reported with each finding.</param>
38:     /// <param name="source">File text.</param>
39:     internal static IReadOnlyList<UnitSuitePlatformFinding> Scan(string relativePath, string source)
40:     {
41:         ArgumentNullException.ThrowIfNull(relativePath);
42:         ArgumentNullException.ThrowIfNull(source);
43:         var original = source.Replace("\r\n", "\n", StringComparison.Ordinal).Split('\n');
44:         var code = StripCommentsAndStrings(source).Replace("\r\n", "\n", StringComparison.Ordinal).Split('\n');
45: 
46:         var open = new Stack<TypeScope>();
47:         var hits = new List<(int Line, string Kind, TypeScope? Owner)>();
48:         var attributeHits = new List<(int Line, string Kind)>();
49:         TypeScope? pending = null;
50:         var depth = 0;
51: 
52:         for (var i = 0; i < code.Length; i++)
53:         {
54:             var line = code[i];
55:             var trimmed = line.Trim();
56:             var declaration = TypeDeclaration.Match(line);
57:             if (declaration.Success)
58:             {
59:                 pending = new TypeScope(
60:                     declaration.Groups[1].Value,
61:                     HasIntegrationTrait(original, code, i),
62:                     open.Count > 0 ? open.Peek() : null,
63:                     depth);
64:             }
65: 
66:             if (open.Count > 0 && TestAttribute.IsMatch(line))
67:                 open.Peek().HasTests = true;
68: 
69:             var lineHits = Rules.Where(rule => rule.Pattern.IsMatch(line)).Select(rule => rule.Kind).ToList();
70:             if (!declaration.Success && trimmed.StartsWith('['))
71:             {
72:                 // Attribute lines belong to the type or member declared after them.
73:                 attributeHits.AddRange(lineHits.Select(kind => (i + 1, kind)));
74:             }
75:             else
76:             {
77:                 if (trimmed.Length > 0)
78:                 {
79:                     var target = declaration.Success ? pending : (open.Count > 0 ? open.Peek() : null);
80:                     hits.AddRange(attributeHits.Select(hit => (hit.Line, hit.Kind, target)));
81:                     attributeHits.Clear();
82:                 }
83: 
84:                 hits.AddRange(lineHits.Select(kind => (i + 1, kind, pending ?? (open.Count > 0 ? open.Peek() : null))));
85:             }
86: 
87:             foreach (var ch in line)
88:             {
89:                 if (ch == '{')
90:                 {
91:                     depth++;
92:                     if (pending is not null)
93:                     {
94:                         pending.Depth = depth;
95:                         open.Push(pending);
96:                         pending = null;
97:                     }
98:                 }
99:                 else if (ch == '}')
100:                 {
101:                     while (open.Count > 0 && open.Peek().Depth >= depth)
102:                         open.Pop();
103:                     depth--;
104:                 }
105:                 else if (ch == ';' && pending is not null && depth == pending.DeclaredDepth)
106:                 {
107:                     // A positional record or a declaration without a body ends here.
108:                     pending = null;
109:                 }
110:             }
111:         }
112: 
113:         var findings = new List<UnitSuitePlatformFinding>();
114:         foreach (var (line, kind, owner) in hits)
115:         {
116:             var testClass = owner;
117:             while (testClass is not null && !testClass.IsTestClass)
118:                 testClass = testClass.Parent;
119:             if (testClass is null || testClass.IsIntegration)
120:                 continue;
121:             findings.Add(new UnitSuitePlatformFinding(relativePath, line, kind, testClass.Name));
122:         }
123: 
124:         return findings;
125:     }
126: 
127:     /// <summary>
128:     /// Replaces the contents of comments, string literals (regular, verbatim, interpolated, raw) and character
129:     /// literals with spaces, keeping every newline so line numbers stay the same.
130:     /// </summary>
131:     /// <param name="source">C# source text.</param>
132:     internal static string StripCommentsAndStrings(string source)
133:     {
134:         ArgumentNullException.ThrowIfNull(source);
135:         var result = new StringBuilder(source.Length);
136:         var i = 0;
137:         while (i < source.Length)
138:         {
139:             var c = source[i];
140:             var next = i + 1 < source.Length ? source[i + 1] : '\0';
141:             if (c == '/' && next == '/')
142:             {
143:                 while (i < source.Length && source[i] != '\n')
144:                     Blank(result, source[i++]);
145:             }
146:             else if (c == '/' && next == '*')
147:             {
148:                 Blank(result, source[i++]);
149:                 Blank(result, source[i++]);
150:                 while (i < source.Length && !(source[i] == '*' && i + 1 < source.Length && source[i + 1] == '/'))
151:                     Blank(result, source[i++]);
152:                 if (i < source.Length)
153:                 {
154:                     Blank(result, source[i++]);
155:                     Blank(result, source[i++]);
156:                 }
157:             }
158:             else if (c == '"' || ((c == '@' || c == '$') && (next == '"' || next == '@' || next == '$')))
159:             {
160:                 var verbatim = false;
161:                 while (i < source.Length && source[i] != '"')
162:                 {
163:                     verbatim |= source[i] == '@';
164:                     result.Append(source[i++]);
165:                 }
166: 
167:                 var quotes = 0;
168:                 while (i + quotes < source.Length && source[i + quotes] == '"')
169:                     quotes++;
170:                 if (quotes >= 3)
171:                 {
172:                     for (var q = 0; q < quotes; q++)
173:                         result.Append(source[i++]);
174:                     while (i < source.Length && !IsQuoteRun(source, i, quotes))
175:                         Blank(result, source[i++]);
176:                     for (var q = 0; q < quotes && i < source.Length; q++)
177:                         result.Append(source[i++]);
178:                 }
179:                 else
180:                 {
181:                     result.Append(source[i++]);
182:                     while (i < source.Length)
183:                     {
184:                         if (verbatim && source[i] == '"' && i + 1 < source.Length && source[i + 1] == '"')
185:                         {
186:                             Blank(result, source[i++]);
187:                             Blank(result, source[i++]);
188:                         }
189:                         else if (!verbatim && source[i] == '\\' && i + 1 < source.Length)
190:                         {
191:                             Blank(result, source[i++]);
192:                             Blank(result, source[i++]);
193:                         }
194:                         else if (source[i] == '"' || (!verbatim && source[i] == '\n'))
195:                         {
196:                             break;
197:                         }
198:                         else
199:                         {
200:                             Blank(result, source[i++]);
201:                         }
202:                     }
203: 
204:                     if (i < source.Length && source[i] == '"')
205:                         result.Append(source[i++]);
206:                 }
207:             }
208:             else if (c == '\'')
209:             {
210:                 result.Append(source[i++]);
211:                 while (i < source.Length && source[i] != '\'' && source[i] != '\n')
212:                 {
213:                     if (source[i] == '\\' && i + 1 < source.Length)
214:                         Blank(result, source[i++]);
215:                     Blank(result, source[i++]);
216:                 }
217: 
218:                 if (i < source.Length && source[i] == '\'')
219:                     result.Append(source[i++]);
220:             }
221:             else
222:             {
223:                 result.Append(source[i++]);
224:             }
225:         }
226: 
227:         return result.ToString();
228:     }
229: 
230:     private static void Blank(StringBuilder result, char c) => result.Append(c == '\n' ? '\n' : ' ');
231: 
232:     private static bool IsQuoteRun(string source, int index, int count)
233:     {
234:         for (var q = 0; q < count; q++)
235:         {
236:             if (index + q >= source.Length || source[index + q] != '"')
237:                 return false;
238:         }
239: 
240:         return true;
241:     }
242: 
243:     private static bool HasIntegrationTrait(string[] original, string[] code, int declarationLine)
244:     {
245:         if (IntegrationTrait.IsMatch(original[declarationLine]))
246:             return true;
247:         for (var i = declarationLine - 1; i >= 0; i--)
248:         {
249:             var stripped = code[i].Trim();
250:             if (stripped.Length == 0)
251:                 continue;
252:             if (!stripped.StartsWith('[') && !stripped.EndsWith(']') && !stripped.EndsWith(','))
253:                 break;
254:             if (IntegrationTrait.IsMatch(original[i]))
255:                 return true;
256:         }
257: 
258:         return false;
259:     }
260: 
261:     private sealed class TypeScope(string name, bool hasIntegrationTrait, TypeScope? parent, int declaredDepth)
262:     {
263:         internal string Name { get; } = name;
264: 
265:         internal TypeScope? Parent { get; } = parent;
266: 
267:         internal int DeclaredDepth { get; } = declaredDepth;
268: 
269:         internal int Depth { get; set; } = -1;
270: 
271:         internal bool HasTests { get; set; }
272: 
273:         internal bool IsTestClass => HasTests || Name.EndsWith("Tests", StringComparison.Ordinal);
274: 
275:         internal bool IsIntegration => hasIntegrationTrait || (Parent?.IsIntegration ?? false);
276:     }
277: }
278: 
279: /// <summary>TR-MCP-USECASE-018 (AC-006): one platform-dependent line in a unit test class.</summary>
280: /// <param name="Path">Repository-relative source path.</param>
281: /// <param name="Line">1-based line number.</param>
282: /// <param name="Kind">os-check, os-attribute, skip, or process-host.</param>
283: /// <param name="TestClass">Unit test class that holds the line.</param>
284: internal sealed record UnitSuitePlatformFinding(string Path, int Line, string Kind, string TestClass)
285: {
286:     /// <inheritdoc />
287:     public override string ToString() => $"{Path}:{Line} {Kind} in {TestClass}";
288: }
