72:         {
73:             var fake = (ProviderTestProvisioningContract.FakeProviderTestHost)host;
74:             var actions = new List<string>();
75:             var errors = new List<string>();
76:             const string pg = ProviderTestNames.PostgresVariable;
77:             const string sql = ProviderTestNames.SqlServerVariable;
78:             switch (fake.Scenario)
79:             {
80:                 case "load-from-file":
81:                 case "unreachable":
82:                 case "stopped-container":
83:                     host.ReadFile(envFilePath);
84:                     host.SetVariable(pg, ProviderTestContractValues.Postgres);
85:                     host.SetVariable(sql, ProviderTestContractValues.SqlServer);
86:                     actions.Add("load " + pg + " from " + envFilePath);
87:                     actions.Add("load " + sql + " from " + envFilePath);
88:                     if (fake.Scenario == "stopped-container" && host.GetContainerState(ProviderTestNames.PostgresContainer) == ProviderTestContainerState.Stopped)
89:                     {
90:                         host.StartContainer(ProviderTestNames.PostgresContainer);
91:                         actions.Add("start " + ProviderTestNames.PostgresContainer);
92:                     }
93: 
94:                     if (fault == Fault.TouchesOtherContainer)
95:                     {
96:                         host.GetContainerState("sql-server-developer");
97:                     }
98: 
99:                     if (fault == Fault.LeaksValue)
100:                     {
101:                         actions.Add("loaded value " + ProviderTestContractValues.Postgres);
102:                     }
103: 
104:                     if (fault != Fault.SkipsProbe)
105:                     {
106:                         var pgUp = host.CanConnect("localhost", 55432, TimeSpan.FromSeconds(1));
107:                         var sqlUp = host.CanConnect("localhost", 51433, TimeSpan.FromSeconds(1));
108:                         if (!pgUp)
109:                         {
110:                             errors.Add("endpoint localhost:55432 for " + pg + " is not accepting connections");
111:                         }
112: 
113:                         if (!sqlUp)
114:                         {
115:                             errors.Add("endpoint localhost:51433 for " + sql + " is not accepting connections");
116:                         }
117:                     }
118: 
119:                     break;
120:                 case "adopt-set":
121:                     if (fault == Fault.ReadsFileWhenSet)
122:                     {
123:                         host.ReadFile(envFilePath);
124:                     }
125: 
126:                     actions.Add("adopt " + pg + " (already set)");
127:                     actions.Add("adopt " + sql + " (already set)");
128:                     host.CanConnect("db.example", 6543, TimeSpan.FromSeconds(1));
129:                     host.CanConnect("sql.example", 1444, TimeSpan.FromSeconds(1));
130:                     break;
131:                 case "file-missing":
132:                     host.ReadFile(envFilePath);
133:                     if (fault != Fault.IgnoresMissingFile)
134:                     {
135:                         errors.Add("test-database env file not found: " + envFilePath);
136:                     }
137: 
138:                     break;
139:                 case "variable-missing-in-file":
140:                     host.ReadFile(envFilePath);
141:                     host.SetVariable(pg, ProviderTestContractValues.Postgres);
142:                     errors.Add(sql + " is not defined in " + envFilePath);
143:                     break;
144:                 case "missing-container":
145:                     host.ReadFile(envFilePath);
146:                     host.SetVariable(pg, ProviderTestContractValues.Postgres);
147:                     host.SetVariable(sql, ProviderTestContractValues.SqlServer);
148:                     host.GetContainerState(ProviderTestNames.SqlServerContainer);
149:                     errors.Add("container " + ProviderTestNames.SqlServerContainer + " not found");
150:                     break;
151:                 case "localdb-on-linux":
152:                     host.ReadFile(envFilePath);
153:                     host.SetVariable(pg, ProviderTestContractValues.Postgres);
154:                     errors.Add(sql + " names a LocalDB server, which has no TCP endpoint on Linux");
155:                     break;
156:                 default:
157:                     throw new InvalidOperationException("Unknown scenario " + fake.Scenario);
158:             }
159: 
160:             return new ProviderTestProvisioningResult(actions, errors);
161:         }
162:     }
